import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import type { PdfPage, TextLine } from "../src/pdf/extractLines.js";
import { parsePages, parseUsBankStatement, statementToCsv, UsBankParseError } from "../src/index.js";

const TEST_DATA = fileURLToPath(new URL("../../../test-data/", import.meta.url));
// Fictional statement generated by scripts/make-sample-statement.ts (npm run sample:usbank).
const SAMPLE = join(TEST_DATA, "usbank-sample-statement.pdf");

describe("sample statement PDF", async () => {
  const statement = await parseUsBankStatement(readFileSync(SAMPLE), { strict: true });
  const [checking, savings] = statement.accounts;

  it("reads the header", () => {
    expect(statement.period).toEqual({ start: "2025-12-09", end: "2026-01-08" });
    expect(statement.accountNumber).toBe("1234");
    expect(statement.customerLines).toEqual(["ALEX SAMPLE", "JORDAN SAMPLE", "123 EXAMPLE ST", "ANYTOWN ST 00000-0000"]);
  });

  it("finds each account and skips the check images page", () => {
    expect(statement.accounts.map((a) => [a.name, a.accountNumber])).toEqual([
      ["U.S. BANK SMARTLY CHECKING", "1234"],
      ["U.S. BANK STANDARD SAVINGS", "5678"],
    ]);
  });

  it("reads the account summary", () => {
    expect(checking!.summary).toMatchObject({
      beginningBalance: 5231.17,
      endingBalance: 6431,
      daysInPeriod: 31,
      averageBalance: 5487.61,
    });
  });

  it("parses every transaction across page breaks and passes all cross-checks", () => {
    expect(checking!.validation).toEqual({ ok: true, issues: [] });
    const counts = Object.groupBy(checking!.transactions, (t) => t.section);
    expect(counts["Deposits / Credits"]).toHaveLength(6);
    expect(counts["Card Withdrawals"]).toHaveLength(29);
    expect(counts["Other Withdrawals"]).toHaveLength(16);
    expect(new Set(checking!.transactions.map((t) => t.page))).toEqual(new Set([3, 4, 5]));
    expect(checking!.dailyBalances).toHaveLength(24);
    const dates = checking!.dailyBalances.map((b) => b.date);
    expect(dates).toEqual([...dates].sort());
    expect(dates[0]).toBe("2025-12-09");
    expect(checking!.dailyBalances.at(-1)).toEqual({ date: "2026-01-08", balance: 6431 });
  });

  it("parses the varied row layouts", () => {
    const find = (s: string) =>
      checking!.transactions.find((t) => t.description.includes(s) || t.type === s || t.details.some((d) => d.includes(s)))!;

    expect(find("PAYROLL")).toEqual({
      date: "2025-12-12",
      section: "Deposits / Credits",
      type: "Electronic Deposit",
      description: "From EXAMPLE CORP",
      details: [expect.stringMatching(/^REF=\d{15}N00 PAYROLL 0000000001$/)],
      refNumber: null,
      amount: 2150,
      transactionDate: null,
      cardLast4: null,
      page: 3,
    });
    expect(find("EXAMPLE ELECTRONICS")).toMatchObject({
      type: "Debit Purchase - VISA",
      description: "On 121625 LAKEVIEW ST",
      refNumber: expect.stringMatching(/^\d{10}$/),
      amount: -1299.99,
      transactionDate: "2025-12-16",
      cardLast4: "4321",
    });
    expect(find("SAMPLE HARDWARE")).toMatchObject({
      type: "Debit Purchase",
      description: "SAMPLE HARDWARE RIVERTON ST",
      refNumber: expect.stringMatching(/^\d{10}$/),
      amount: -27.99,
      transactionDate: "2025-12-11",
    });
    expect(find("Credit Card")).toMatchObject({ type: "Mobile Banking Payment", details: [], amount: -500 });
    expect(find("Customer Withdrawal")).toMatchObject({ description: "", refNumber: "1111111111", amount: -300 });
    expect(find("EXAMPLE MORTGAGE")).toMatchObject({ date: "2026-01-02", amount: -1850, page: 5 });
  });

  it("parses a savings account without a Balance Summary", () => {
    expect(savings!.validation).toEqual({ ok: true, issues: [] });
    expect(savings!.dailyBalances).toEqual([]);
    expect(savings!.transactions.map((t) => [t.date, t.section, t.amount])).toEqual([
      ["2026-01-08", "Deposits / Credits", 0.08],
      ["2025-12-18", "Other Withdrawals", -500],
      ["2025-12-30", "Other Withdrawals", -250],
    ]);
  });

  it("keeps the right-hand summary column separate from section totals", () => {
    expect(savings!.summary.lines.map((l) => l.label)).toEqual([
      "Beginning Balance on Dec 9",
      "Deposits / Credits",
      "Other Withdrawals",
      "Ending Balance on Jan 8, 2026",
    ]);
    expect(savings!.summary.details).toEqual([
      { label: "Interest Earned this Period", value: 0.08 },
      { label: "Interest Paid this Year", value: 0.08 },
      { label: "Number of Days in Statement Period", value: 31 },
    ]);
    expect(savings!.summary.daysInPeriod).toBe(31);
  });
});

// Real statements are kept out of the repo; drop them in test-data/manual/ to check they still parse.
const MANUAL = join(TEST_DATA, "manual");
const manualPdfs = existsSync(MANUAL) ? readdirSync(MANUAL).filter((f) => f.toLowerCase().endsWith(".pdf")) : [];

describe.skipIf(manualPdfs.length === 0)("local statements in test-data/manual", () => {
  it.each(manualPdfs)("%s parses and passes all cross-checks", async (file) => {
    const statement = await parseUsBankStatement(readFileSync(join(MANUAL, file)), { strict: true });
    expect(statement.accounts.length).toBeGreaterThan(0);
    for (const account of statement.accounts) expect(account.accountNumber, account.name).toBeTruthy();
  });
});

// Synthetic statements built from positioned text, mirroring the real layout's x-coordinates.
type Row = [y: number, ...cells: [x: number, str: string][]];

function page(n: number, rows: Row[]): PdfPage {
  const lines: TextLine[] = rows.map(([y, ...cells]) => ({
    page: n,
    y,
    items: cells.map(([x, str]) => ({ x, y, str, width: str.length * 4 })),
  }));
  return { page: n, lines };
}

const coverPage = (start: string, end: string) =>
  page(1, [
    [749, [527, "Account Number:"]],
    [737, [528, "1234"]],
    [713, [543, start]],
    [689, [550, end]],
  ]);

const TABLE_HEADER: Row = [460, [20, "Date"], [56, "Description of Transaction"], [409, "Ref Number"], [558, "Amount"]];

function yearEndStatement(depositAmount: string): PdfPage[] {
  return [
    coverPage("Dec 10, 2025", "Jan 9, 2026"),
    page(2, [
      [647, [20, "U.S. BANK SMARTLY CHECKING"], [532, "Member FDIC"]],
      [624, [20, "Account Summary"]],
      [614, [20, "Beginning Balance on Dec 10"], [193, "$"], [253, "100.00"]],
      [603, [20, "Deposits / Credits"], [253, "50.00"]],
      [593, [20, "Other Withdrawals"], [258, "30.00-"]],
      [565, [52, "Ending Balance on Jan 9, 2026"], [193, "$"], [253, "120.00"]],
      [471, [20, "Deposits / Credits"]],
      TABLE_HEADER,
      [450, [20, "Dec 31"], [56, "Electronic Deposit"], [207, "From ACME"], [554, depositAmount]],
      [440, [71, "REF=1"], [222, "PAYROLL"]],
      [420, [352, "Total Deposits / Credits"], [495, "$"], [549, "50.00"]],
      [400, [20, "Other Withdrawals"]],
      [390, [20, "Date"], [56, "Description of Transaction"], [409, "Ref Number"], [558, "Amount"]],
      [380, [20, "Jan"], [44, "2"], [56, "Electronic Withdrawal"], [207, "To UTILITY"], [563, "30.00-"]],
      [360, [349, "Total Other Withdrawals"], [495, "$"], [551, "30.00-"]],
      [340, [20, "Balance Summary"]],
      [330, [20, "Date"], [115, "Ending Balance"], [207, "Date"], [303, "Ending Balance"]],
      [320, [20, "Dec 31"], [135, "150.00"], [207, "Jan"], [230, "2"], [322, "120.00"]],
    ]),
  ];
}

describe("synthetic statements", () => {
  it("assigns the right year to dates in a statement spanning New Year", () => {
    const statement = parsePages(yearEndStatement("50.00"));
    const account = statement.accounts[0]!;
    expect(statement.period).toEqual({ start: "2025-12-10", end: "2026-01-09" });
    expect(account.validation.issues).toEqual([]);
    expect(account.transactions.map((t) => [t.date, t.amount])).toEqual([
      ["2025-12-31", 50],
      ["2026-01-02", -30],
    ]);
    expect(account.dailyBalances.map((b) => b.date)).toEqual(["2025-12-31", "2026-01-02"]);
  });

  it("reports validation failures when amounts don't reconcile", () => {
    const account = parsePages(yearEndStatement("55.00")).accounts[0]!;
    expect(account.validation.ok).toBe(false);
    expect(account.validation.issues).toEqual(
      expect.arrayContaining([
        expect.stringContaining("ending balance is 120.00"),
        expect.stringContaining('Section "Deposits / Credits" sums to 55.00'),
        expect.stringContaining("Running balance on 2025-12-31 is 155.00"),
      ]),
    );
  });

  it("does not attach repeated page headers to the last transaction on the previous page", () => {
    const [cover, first] = yearEndStatement("50.00");
    // Split the deposit section across a page break.
    const split = first!.lines.findIndex((l) => l.items[0]?.str === "Total Deposits / Credits");
    const before = { page: 2, lines: first!.lines.slice(0, split) };
    const after = page(3, [
      [758, [515, "Uni-Statement"]],
      [734, [528, "1234"]],
      [668, [550, "Page 2 of 2"]],
      [647, [20, "U.S. BANK SMARTLY CHECKING"], [517, "(CONTINUED)"]],
      [624, [20, "Deposits / Credits (continued)"]],
    ]);
    after.lines.push(...first!.lines.slice(split).map((l) => ({ ...l, page: 3 })));

    const account = parsePages([cover!, before, after]).accounts[0]!;
    expect(account.validation.issues).toEqual([]);
    expect(account.transactions[0]!.details).toEqual(["REF=1 PAYROLL"]);
  });

  it("takes the section from the (continued) heading when a table resumes on a new page", () => {
    const [cover, first] = yearEndStatement("50.00");
    // End page 2 mid-way through "Other Withdrawals", after a footer line that looks like a heading.
    const split = first!.lines.findIndex((l) => l.items[0]?.str === "Jan");
    const before = { page: 2, lines: [...first!.lines.slice(0, split), ...page(2, [[38, [20, "call 800-872-2657."]]]).lines] };
    const after = page(3, [
      [758, [515, "Uni-Statement"]],
      [647, [20, "U.S. BANK SMARTLY CHECKING"], [517, "(CONTINUED)"]],
      [624, [20, "Other Withdrawals (continued)"]],
      [614, [20, "Date"], [56, "Description of Transaction"], [409, "Ref Number"], [558, "Amount"]],
    ]);
    after.lines.push(...first!.lines.slice(split).map((l) => ({ ...l, page: 3 })));

    const account = parsePages([cover!, before, after]).accounts[0]!;
    expect(account.validation.issues).toEqual([]);
    expect(account.transactions.map((t) => t.section)).toEqual(["Deposits / Credits", "Other Withdrawals"]);
  });

  it("validates statements without a Balance Summary table", () => {
    const [cover, first] = yearEndStatement("50.00");
    const end = first!.lines.findIndex((l) => l.items[0]?.str === "Balance Summary");
    const account = parsePages([cover!, { page: 2, lines: first!.lines.slice(0, end) }]).accounts[0]!;
    expect(account.dailyBalances).toEqual([]);
    expect(account.validation.issues).toEqual([]);
  });

  it("skips check image pages and resumes an account continued after them", () => {
    const [cover, first] = yearEndStatement("50.00");
    // Split at the "Other Withdrawals" section heading, not the Account Summary line of the same name.
    const split = first!.lines.findIndex((l) => l.items.length === 1 && l.items[0]?.str === "Other Withdrawals");
    const before = { page: 2, lines: first!.lines.slice(0, split) };
    const images = page(3, [
      [647, [20, "IMAGES FOR YOUR U.S. BANK SMARTLY CHECKING ACCOUNT"], [532, "Member FDIC"]],
      [636, [452, "Account Number"], [527, "1234"]],
      [500, [20, "1001"], [128, "Jan 2"], [232, "30.00"]],
    ]);
    const after = page(4, [[647, [20, "U.S. BANK SMARTLY CHECKING"], [517, "(CONTINUED)"]]]);
    after.lines.push(...first!.lines.slice(split).map((l) => ({ ...l, page: 4 })));

    const statement = parsePages([cover!, before, images, after]);
    expect(statement.accounts).toHaveLength(1);
    expect(statement.accounts[0]!.validation.issues).toEqual([]);
    expect(statement.accounts[0]!.transactions).toHaveLength(2);
  });

  it("rejects documents that are not U.S. Bank statements", () => {
    expect(() => parsePages([coverPage("Dec 10, 2025", "Jan 9, 2026")])).toThrow(UsBankParseError);
  });
});

describe("statementToCsv", () => {
  it("writes one escaped row per transaction", () => {
    const statement = parsePages(yearEndStatement("50.00"));
    statement.accounts[0]!.transactions[0]!.description = 'From "ACME", Inc';
    expect(statementToCsv(statement).split("\r\n")).toEqual([
      "Account,Date,Transaction Date,Section,Type,Description,Details,Ref Number,Card,Amount",
      '1234,2025-12-31,,Deposits / Credits,Electronic Deposit,"From ""ACME"", Inc",REF=1 PAYROLL,,,50.00',
      "1234,2026-01-02,,Other Withdrawals,Electronic Withdrawal,To UTILITY,,,,-30.00",
      "",
    ]);
  });
});
